import sys


def main():
    data = sys.stdin.read().split()
    n, m = int(data[0]), int(data[1])
    grid = data[2:2 + n]
    present = 0
    for row in grid:
        for ch in row:
            if ch in 'abcdef':
                present |= 1 << (ord(ch) - ord('a'))
    masks = [mask for mask in range(64) if mask & present == mask]
    INF = float('inf')
    dist = {}
    sr = sc = -1
    for r in range(n):
        for c in range(m):
            for mask in masks:
                dist[(r, c, mask)] = INF
            if grid[r][c] == 'S':
                sr, sc = r, c
    dist[(sr, sc, 0)] = 0
    order = [(r, c, mask) for r in range(n) for c in range(m) for mask in masks]
    changed = True
    rnd = 0
    while changed:
        changed = False
        seq = order if rnd % 2 == 0 else order[::-1]
        rnd += 1
        for (r, c, mask) in seq:
            d = dist[(r, c, mask)]
            if d == INF:
                continue
            for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                nr, nc = r + dr, c + dc
                if nr < 0 or nr >= n or nc < 0 or nc >= m:
                    continue
                ch = grid[nr][nc]
                if ch == '#':
                    continue
                if ch in 'ABCDEF' and not mask & (1 << (ord(ch) - ord('A'))):
                    continue
                nmask = mask
                if ch in 'abcdef':
                    nmask = mask | (1 << (ord(ch) - ord('a')))
                if d + 1 < dist[(nr, nc, nmask)]:
                    dist[(nr, nc, nmask)] = d + 1
                    changed = True
    best = INF
    for r in range(n):
        for c in range(m):
            if grid[r][c] == 'T':
                for mask in masks:
                    best = min(best, dist[(r, c, mask)])
    print(-1 if best == INF else best)


main()
